package com.hostel.hostelmanagement.entity; import jakarta.persistence.*; import java.time.LocalDateTime; @Entity public class Notice { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; String title; @Column(length=3000) String content; LocalDateTime createdAt=LocalDateTime.now(); public Notice(){} public Long getId(){return id;} public String getTitle(){return title;} public String getContent(){return content;} public LocalDateTime getCreatedAt(){return createdAt;} public void setId(Long v){id=v;} public void setTitle(String v){title=v;} public void setContent(String v){content=v;} }